 mechanisms=["Surfactant deficiency raises alveolar surface tension, so alveoli collapse at end-expiration (RDS).", "Collapse reduces lung compliance and causes hypoxaemia and increased work of breathing.", "Grunting is the baby's own PEEP against a partly closed glottis.", "CPAP and surfactant keep alveoli open."],
