 ruleIn=[
  inv("specializedAdjunctive", "Silverman-Anderson score (SAS)", "Bedside score", "Severity", "0", "1–3 mild; 4 moderate; 5 or more severe", "Guides oxygen, CPAP and ventilation (ICMR STW).", "nrd", RS),
  inv("specializedAdjunctive", "Pulse oximetry", "SpO2", "Hypoxaemia", "91–95% on treatment (target)", "Below 91%", "Start or increase support; keep at or below 95% (ICMR STW).", "nrd", RS),
  inv("specializedAdjunctive", "Respiratory rate and capillary filling time", "Bedside", "Distress and shock", "Respiratory rate 40–60/min; CFT under 3 seconds", "Respiratory rate above 60/min; CFT 3 seconds or more", "Monitor regularly (ICMR STW).", "nrd", RS),
  inv("firstLineImaging", "Chest X-ray", "Chest radiograph", "Cause of distress", "Clear, well-expanded lungs", "Ground-glass with air bronchograms (RDS), infiltrates, pneumothorax", "Only if distress persists beyond 6 hours, worsens or diagnosis unclear (ICMR STW).", "nrd", WN),
  inv("laboratory", "Blood glucose", "Capillary glucose", "Hypoglycaemia", "Above 45 mg/dL", "Below 45 mg/dL", "See Neonatal hypoglycaemia topic.", "nrd", RS)],
