 management=[
  step("assess", "Assess", "At birth or onset", ["Score SAS; measure SpO2, respiratory rate and CFT (ICMR STW).", "Avoid unnecessary CBC, CRP and routine ABG (ICMR STW)."]),
  step("oxygen", "Oxygen", "Immediately", ["Nasal prongs 0.5–1.0 L/min, maximum 2 L/min; target SpO2 91–95% (ICMR STW).", "Wean if SpO2 above 95% (ICMR STW)."]),
  step("cpap", "CPAP", "Early", ["32 weeks or more: CPAP if SAS 4 or more or no improvement on oxygen (ICMR STW).", "Below 32 weeks: CPAP if SpO2 below 91% or any distress; early CPAP if SAS 3 or more (ICMR STW).", "RDS: consider surfactant (see medicines)."]),
  step("feed", "Feeds and fluids", "Throughout", ["Breastfeed if respiratory rate below 70/min and not on support; otherwise orogastric feeds (ICMR STW).", "IV fluids only for severe distress or contraindication to enteral feeds (ICMR STW)."]),
  step("escalate", "Ventilate or refer", "As needed", ["Severe distress (SAS 5 or more or FiO2 above 60–70%), CPAP failure, shock or repeated apnoea: ventilate or refer with the transport workflow (ICMR STW).", "Pneumonia or sepsis: treat per unit protocol and the neonatal sepsis workflow (ICMR STW)."])],
 branches=[("Oxygen therapy", "Newborn with respiratory distress or SpO2 below 91%."), ("Respiratory distress syndrome (preterm)", "Preterm newborn with RDS on CPAP or ventilation, in a unit able to intubate.")],
